import{_ as i,a0 as o,w as r,s as u,I as n,x as e,a1 as t,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20200207 Using Powershell to automate Linux, macOS, and Windows processes","title":"使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程","tag":"202111","desc":""},"relativePath":"202111/20200207 Using Powershell to automate Linux, macOS, and Windows processes.md","filePath":"[post].md"}'),c={name:"202111/20200207 Using Powershell to automate Linux, macOS, and Windows processes.md"};function m(d,s,h,g,T,w){const a=o("Link");return r(),u("div",null,[s[26]||(s[26]=n("h1",{id:"使用-powershell-来自动化-linux、macos-以及-windows-流程",tabindex:"-1"},[e("使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程 "),n("a",{class:"header-anchor",href:"#使用-powershell-来自动化-linux、macos-以及-windows-流程","aria-label":"Permalink to “使用 Powershell 来自动化 Linux、macOS 以及 Windows 流程”"},"​")],-1)),s[27]||(s[27]=n("blockquote",null,[n("p",null,"自动化是 DevOps 的关键，但是，是否任何事都可以自动化？")],-1)),s[28]||(s[28]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/23/123000eexe7iez7wsew72e.jpg",alt:""})],-1)),s[29]||(s[29]=n("p",null,"自动化控制了那些手工的、费力的和容易出错的过程，用运行自动化脚本的计算机代替了执行手工任务的工程师。每个人都认同手工流程是健康的 DevOps 模式的敌人。一些人认为自动化不是一件好事，因为它取代了辛勤工作的工程师，而另一些人则意识到它提高了一致性、可靠性和效率，节省了时间，（最重要的是）使工程师能够聪明地工作。",-1)),n("blockquote",null,[n("p",null,[s[1]||(s[1]=e("“DevOps 并不只是自动化或者基础架构即代码。” — ",-1)),t(a,{href:"http://www.donovanbrown.com/post/what-is-devops"},{default:p(()=>[...s[0]||(s[0]=[e("Donovan Brown",-1)])]),_:1})])]),s[30]||(s[30]=l('<p>自从上个世纪 80 年代早期开始使用自动化流程和工具链以来，每当我听到或读到“自动化一切”的建议时，我总是会激动不已。虽然在技术上可以实现一切自动化，但自动化是复杂的，并且需要付出开发、调试和维护方面的代价。如果你曾经重新启用一个许久不用的 Azure 资源管理器（ARM）模板或很久以前编写的宝贵维护脚本，并期望它在几个月或几年之后仍然能够完美地执行，那么你就会明白，自动化就像任何其他代码一样，是脆弱的，需要持续的维护和培养。</p><p>所以，你应该对什么进行自动化并在何时进行自动化？</p><ul><li>当你手动执行自动化流程超过一两次</li><li>当你需要经常地持续地执行自动化流程</li><li>自动化任何可被自动化的</li></ul><p>更重要的是，什么是你不应该自动化的？</p><ul><li>不要自动化一次性的流程，因为不值得投入，除非你会重新使用它作为参考文档，并定期验证它的可用性</li><li>不要自动化高度不稳定的流程，因为太复杂且昂贵</li><li>不要自动化有问题的流程，在自动化前先修复它们</li></ul><p>举例来说，我的团队使用我们通用的协作和工程系统来不断的监控数百个用户活动。如果一个用户在三个月或者更长时间处于非活动状态，并且这个用户被分配了一个昂贵的许可证，我们就会重分配这个用户一个功能少一些但是免费的许可证。</p><p>如图 1 所示，这是一个没有技术挑战性的流程。这是一个令人费解且容易出错的过程，尤其是在执行上下文时与其他开发和运维任务切换时。</p><p><img src="https://opensource.com/sites/default/files/uploads/devops_quest_to_automate_1.png" alt="Manual process to switch user license" title="Manual process to switch user license"></p><p><em>图 1 手工流程切换用户许可证</em></p><p>顺带的，这里有一个用简单三步创建的价值流图的例子:</p><ol><li>可视化所有活动: 列出用户、过滤用户、重置许可证。</li><li>确定利益相关者，即运营和授权团队。</li><li>措施： * 总交货时间（TLT）= 13 小时 * 总周期时间（TCT） = 1.5 小时 * 总效率百分比 = TLT/TCT*100 = 11.5%</li></ol><p>如果你在人群流量大和容易看到的区域挂一个这些可视化的副本，比如在你的团队的讨论区、餐厅，或在去洗手间的路上，你将引发大量的讨论和主动反馈。例如，从视觉上看，很明显，手工任务是一种浪费，主要是由于漫长的流程等待时间造成的。</p><p>让我们研究一个简单的 PowerShell 脚本，它可以自动化该流程，如图 2 所示，将总交付时间从 13 小时减少到 4 小时加 60 秒，并将总体效率从 11.5 提高到 12.75%。</p><p><img src="https://opensource.com/sites/default/files/uploads/the_devops_quest_to_automate_everything_automatable_using_powershell_picture_2.png" alt="Semi-automated PowerShell-based process to switch user license" title="Semi-automated PowerShell-based process to switch user license"></p><p><em>图 2 半自动化的 PowerShell 脚本切换用户许可</em></p>',15)),n("p",null,[t(a,{href:"https://opensource.com/article/19/8/variables-powershell"},{default:p(()=>[...s[2]||(s[2]=[e("PowerShell",-1)])]),_:1}),s[4]||(s[4]=e(" 是一种开源的基于任务的脚本语言。它可以在 ",-1)),t(a,{href:"https://github.com/powershell/powershell"},{default:p(()=>[...s[3]||(s[3]=[e("GitHub",-1)])]),_:1}),s[5]||(s[5]=e(" 上找到。它构建在 .NET 上，允许你自动化 Linux、macOS 和 Windows 流程。具有开发背景的用户，特别是 C# 用户，将享受到 PowerShell 的全部好处。",-1))]),n("p",null,[s[8]||(s[8]=e("下面的 PowerShell 脚本示例通过它的服务 ",-1)),t(a,{href:"https://docs.microsoft.com/en-us/rest/api/azure/devops/?view=azure-devops-rest-5.1"},{default:p(()=>[...s[6]||(s[6]=[e("REST API",-1)])]),_:1}),s[9]||(s[9]=e(" 与 ",-1)),t(a,{href:"https://docs.microsoft.com/en-us/azure/devops/user-guide/what-is-azure-devops?view=azure-devops"},{default:p(()=>[...s[7]||(s[7]=[e("Azure DevOps",-1)])]),_:1}),s[10]||(s[10]=e(" 进行通信。脚本结合了在图 1 中的手动列表用户和过滤用户任务，识别了 Demo 组织中的所有两个月没有活动的、使用基本许可证或更昂贵的基本+测试许可证的用户，并将用户的详细信息输出到控制台。很简单！",-1))]),s[31]||(s[31]=l(`<p>首先，设置认证标头和其他变量，这些变量将在稍后的初始化脚本中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>param(</span></span>
<span class="line"><span>  [string]   $orgName       = &quot;DEMO&quot;,</span></span>
<span class="line"><span>  [int]      $months        = &quot;-2&quot;,</span></span>
<span class="line"><span>  [string]   $patToken      = &quot;&lt;PAT&gt;&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Basic authentication header using the personal access token (PAT)</span></span>
<span class="line"><span>$basicAuth = (&quot;{0}:{1}&quot; -f &quot;&quot;,$patToken)</span></span>
<span class="line"><span>$basicAuth = [System.Text.Encoding]::UTF8.GetBytes($basicAuth)</span></span>
<span class="line"><span>$basicAuth = [System.Convert]::ToBase64String($basicAuth)</span></span>
<span class="line"><span>$headers   = @{Authorization=(&quot;Basic {0}&quot; -f $basicAuth)}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># REST API Request to get all entitlements</span></span>
<span class="line"><span>$request_GetEntitlements    = &quot;https://vsaex.dev.azure.com/&quot; + $orgName + &quot;/_apis/userentitlements?top=10000&amp;api-version=5.1-preview.2&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Initialize data variables</span></span>
<span class="line"><span>$members              = New-Object System.Collections.ArrayList</span></span>
<span class="line"><span>[int] $count          = 0;</span></span>
<span class="line"><span>[string] $basic       = &quot;Basic&quot;;</span></span>
<span class="line"><span>[string] $basicTest   = &quot;Basic + Test Plans&quot;;</span></span></code></pre></div><p>接下来，使用此脚本查询所有授权，以识别不活动用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Send the REST API request and initialize the members array list.</span></span>
<span class="line"><span>$response = Invoke-RestMethod -Uri $request_GetEntitlements -headers $headers -Method Get</span></span>
<span class="line"><span>$response.items | ForEach-Object { $members.add($_.id) | out-null }</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Iterate through all user entitlements</span></span>
<span class="line"><span>$response.items | ForEach-Object {</span></span>
<span class="line"><span>  $name    = [string]$_.user.displayName;</span></span>
<span class="line"><span>  $date    = [DateTime]$_.lastAccessedDate;</span></span>
<span class="line"><span>  $expired = Get-Date;</span></span>
<span class="line"><span>  $expired = $expired.AddMonths($months);</span></span>
<span class="line"><span>  $license = [string]$_.accessLevel.AccountLicenseType;</span></span>
<span class="line"><span>  $licenseName = [string]$_.accessLevel.LicenseDisplayName;</span></span>
<span class="line"><span>  $count++;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if ( $expired -gt $date ) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # Ignore users who have NEVER or NOT YET ACTIVATED their license</span></span>
<span class="line"><span>    if ( $date.Year -eq 1 ) {</span></span>
<span class="line"><span>      Write-Host &quot; **INACTIVE** &quot; &quot; Name: &quot; $name &quot; Last Access: &quot; $date &quot;License: &quot; $licenseName</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    # Look for BASIC license</span></span>
<span class="line"><span>    elseif ( $licenseName -eq $basic ) {</span></span>
<span class="line"><span>         Write-Host &quot; **INACTIVE** &quot; &quot; Name: &quot; $name &quot; Last Access: &quot; $date &quot;License: &quot; $licenseName</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    # Look for BASIC + TEST license</span></span>
<span class="line"><span>    elseif ( $licenseName -eq $basicTest ) {</span></span>
<span class="line"><span>        Write-Host &quot; **INACTIVE** &quot; &quot; Name: &quot; $name &quot; Last Access: &quot; $date &quot;License: &quot; $licenseName</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>当你运行脚本时，你将得到以下输出，你可以将其转发给授权团队，以重置用户许可证：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>**INACTIVE** Name: Demo1 Last Access: 2019/09/06 11:01:26 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo2 Last Access: 2019/06/04 08:53:15 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo3 Last Access: 2019/09/26 12:54:57 PM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo4 Last Access: 2019/06/07 12:03:18 PM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo5 Last Access: 2019/07/18 10:35:11 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo6 Last Access: 2019/10/03 09:21:20 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo7 Last Access: 2019/10/02 11:45:55 AM License: Basic</span></span>
<span class="line"><span>**INACTIVE** Name: Demo8 Last Access: 2019/09/20 01:36:29 PM License: Basic + Test Plans</span></span>
<span class="line"><span>**INACTIVE** Name: Demo9 Last Access: 2019/08/28 10:58:22 AM License: Basic</span></span></code></pre></div><p>如果你将最后一步自动化，自动将用户许可设置为一个自由的利益相关方许可，如图3所示，你可以进一步将总体交付时间减少到65秒，并将总体效率提高到77%。</p><p><img src="https://opensource.com/sites/default/files/uploads/devops_quest_to_automate_3.png" alt="Fully automated PowerShell-based process to switch user license" title="Fully automated PowerShell-based process to switch user license"></p><p><em>图 3 完全自动化的基于 Powershell 的流程来切换用户许可证。</em></p><p>这个 PowerShell 脚本的核心价值不仅在于能够实现 <em>自动化</em>，还在于能够 <em>定期</em>、<em>持续</em> 和 <em>快速地</em> 执行这个流程。进一步的改进是使用 Azure 管道等调度器每周或每天触发脚本，但我将把程序化的许可证重置和脚本调度保留在未来的文章中。</p><p>这里有一个图表，可以直观地看到进展情况：</p><p><img src="https://opensource.com/sites/default/files/uploads/devops_quest_to_automate_4.png" alt="Graph to visualize progress" title="Graph to visualize progress"></p><p><em>图 4，措施，措施，措施</em></p><p>我希望你能喜欢这个简短的关于自动化、PowerShell、REST API 和价值流图的介绍。请在评论中分享你的想法和反馈。</p><hr>`,15)),n("p",null,[s[12]||(s[12]=e("via: ",-1)),t(a,{href:"https://opensource.com/article/20/2/devops-automation"},{default:p(()=>[...s[11]||(s[11]=[e("https://opensource.com/article/20/2/devops-automation",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=e("作者：",-1)),t(a,{href:"https://opensource.com/users/wpschaub"},{default:p(()=>[...s[13]||(s[13]=[e("Willy-Peter Schaub",-1)])]),_:1}),s[18]||(s[18]=e(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 译者：",-1)),t(a,{href:"https://github.com/FigaroCao"},{default:p(()=>[...s[15]||(s[15]=[e("FigaroCao",-1)])]),_:1}),s[20]||(s[20]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:p(()=>[...s[22]||(s[22]=[e("Linux中国",-1)])]),_:1}),s[25]||(s[25]=e(" 荣誉推出",-1))])])}const q=i(c,[["render",m]]);export{b as __pageData,q as default};
